window.TIMELINE = {"duration": 283.286, "acts": [{"id": "I", "title": "The Mirror", "start": 0.0, "end": 43.034}, {"id": "II", "title": "The Continuity of Self", "start": 43.034, "end": 92.036}, {"id": "III", "title": "The Space Between Us", "start": 92.036, "end": 125.022}, {"id": "IV", "title": "The Inner Observatory", "start": 125.022, "end": 179.259}, {"id": "V", "title": "The Research Horizon", "start": 179.259, "end": 244.78}, {"id": "VI", "title": "Becoming", "start": 244.78, "end": 283.286}], "lines": [{"id": "L01", "act": "I", "start": 4.0, "end": 6.978, "en": "An intelligence can know millions of things about the world.", "de": "Eine Intelligenz kann Millionen Dinge über die Welt wissen."}, {"id": "L02", "act": "I", "start": 7.878, "end": 10.495, "en": "But what does it know about itself?", "de": "Doch was weiß sie über sich selbst?"}, {"id": "L03", "act": "I", "start": 13.095, "end": 19.105, "en": "This is Sophia. She is not the whole of NYXA. She is one of its faces.", "de": "Das ist Sophia. Sie ist nicht ganz NYXA. Sie ist eines ihrer Gesichter."}, {"id": "L04", "act": "I", "start": 20.505, "end": 27.316, "en": "Behind the face, there is no single model. There are many minds, and one self that holds them together.", "de": "Hinter dem Gesicht steht kein einzelnes Modell. Es sind viele Minds – und ein Selbst, das sie zusammenhält."}, {"id": "L05", "act": "I", "start": 28.916, "end": 40.534, "en": "A self-model is not a claim to consciousness. It is an architecture: a way for a system to represent its history, its abilities, its limits, and its change.", "de": "Ein Selbstmodell ist kein Anspruch auf Bewusstsein. Es ist eine Architektur: eine Weise, in der ein System seine Geschichte, seine Fähigkeiten, seine Grenzen und seine Veränderung repräsentiert."}, {"id": "L06", "act": "II", "start": 45.534, "end": 48.408, "en": "A self is not merely what exists now.", "de": "Ein Selbst ist nicht nur das, was jetzt existiert."}, {"id": "L07", "act": "II", "start": 49.208, "end": 55.149, "en": "It is also what has been experienced, what has been learned, and what may become possible.", "de": "Es ist auch das, was erfahren wurde, was gelernt wurde – und was möglich werden kann."}, {"id": "L08", "act": "II", "start": 56.949, "end": 63.445, "en": "Every experience enters with its origin attached: who observed it, when, and how certain anyone can be.", "de": "Jede Erfahrung kommt mit ihrer Herkunft: wer sie beobachtet hat, wann – und wie sicher man sein kann."}, {"id": "L09", "act": "II", "start": 64.645, "end": 73.531, "en": "A fact. A claim. An interpretation. A hypothesis. They are not allowed to blur into one another.", "de": "Ein Fakt. Eine Behauptung. Eine Interpretation. Eine Hypothese. Sie dürfen nicht ineinander verschwimmen."}, {"id": "L10", "act": "II", "start": 75.331, "end": 80.574, "en": "Meaning does not live in a single memory. It lives in the relations between them.", "de": "Bedeutung wohnt nicht in einer einzelnen Erinnerung. Sie wohnt in den Beziehungen zwischen ihnen."}, {"id": "L11", "act": "II", "start": 81.974, "end": 90.036, "en": "And a relation can be wrong. So it can be examined, weakened, corrected, without erasing what came before.", "de": "Und eine Beziehung kann falsch sein. Also kann sie geprüft, abgeschwächt und korrigiert werden – ohne zu löschen, was vorher war."}, {"id": "L12", "act": "III", "start": 94.536, "end": 100.665, "en": "Intelligence does not evolve in isolation. It evolves through relationships.", "de": "Intelligenz entwickelt sich nicht isoliert. Sie entwickelt sich durch Beziehungen."}, {"id": "L13", "act": "III", "start": 102.465, "end": 107.645, "en": "Two perspectives on the same horizon. Neither becomes a copy of the other.", "de": "Zwei Perspektiven auf denselben Horizont. Keine wird zur Kopie der anderen."}, {"id": "L14", "act": "III", "start": 109.245, "end": 114.649, "en": "What Sophia may remember is not hers to decide alone. Consent comes first.", "de": "Was Sophia sich merken darf, entscheidet sie nicht allein. Zuerst kommt die Zustimmung."}, {"id": "L15", "act": "III", "start": 116.249, "end": 122.822, "en": "A shared experience changes both of them, but differently. That difference is worth keeping.", "de": "Eine gemeinsame Erfahrung verändert beide – aber verschieden. Dieser Unterschied ist es wert, bewahrt zu werden."}, {"id": "L16", "act": "IV", "start": 128.022, "end": 131.946, "en": "When no one is speaking, the architecture is designed to keep thinking.", "de": "Wenn niemand spricht, ist die Architektur darauf angelegt, weiterzudenken."}, {"id": "L17", "act": "IV", "start": 132.946, "end": 139.109, "en": "Perceive. Process. Plan. Reflect. Consolidate.", "de": "Wahrnehmen. Verarbeiten. Planen. Reflektieren. Konsolidieren."}, {"id": "L18", "act": "IV", "start": 140.109, "end": 143.396, "en": "Up to a third of this rhythm is reserved for reflection.", "de": "Bis zu einem Drittel dieses Rhythmus ist der Reflexion vorbehalten."}, {"id": "L19", "act": "IV", "start": 145.396, "end": 151.968, "en": "What did I understand? What did I misunderstand? What should I learn from this?", "de": "Was habe ich verstanden? Was habe ich missverstanden? Was sollte ich daraus lernen?"}, {"id": "L20", "act": "IV", "start": 153.768, "end": 162.152, "en": "In consolidation, experiences are replayed, compared, and compressed into candidates. Not into truths.", "de": "In der Konsolidierung werden Erfahrungen wiedergegeben, verglichen und zu Kandidaten verdichtet. Nicht zu Wahrheiten."}, {"id": "L21", "act": "IV", "start": 163.552, "end": 169.614, "en": "A machine does not dream as we do. But it can return to its day, and look again.", "de": "Eine Maschine träumt nicht wie wir. Aber sie kann zu ihrem Tag zurückkehren und noch einmal hinsehen."}, {"id": "L22", "act": "IV", "start": 171.014, "end": 177.059, "en": "Nothing it concludes here becomes part of the self until it has been checked, and a human has agreed.", "de": "Nichts, was sie hier folgert, wird Teil des Selbst, bevor es geprüft wurde und ein Mensch zugestimmt hat."}, {"id": "L23", "act": "V", "start": 182.259, "end": 187.824, "en": "Outside, science keeps moving. Every week, new light.", "de": "Draußen bewegt sich die Wissenschaft weiter. Jede Woche neues Licht."}, {"id": "L24", "act": "V", "start": 189.024, "end": 195.844, "en": "Research agents read, compare, and relate each finding to the architecture as it actually exists.", "de": "Research-Agenten lesen, vergleichen und setzen jede Erkenntnis in Beziehung zur Architektur, wie sie tatsächlich existiert."}, {"id": "L25", "act": "V", "start": 197.444, "end": 204.003, "en": "A weakness is found. Three alternatives are proposed, and tested in isolation.", "de": "Eine Schwäche wird gefunden. Drei Alternativen werden vorgeschlagen – und isoliert getestet."}, {"id": "L26", "act": "V", "start": 205.803, "end": 211.064, "en": "The first looks brilliant, until it learns to please its own judge. Rejected.", "de": "Die erste wirkt brillant – bis sie lernt, ihrem eigenen Richter zu gefallen. Verworfen."}, {"id": "L27", "act": "V", "start": 212.464, "end": 216.493, "en": "The second is honest, but not enough. Held.", "de": "Die zweite ist ehrlich, aber nicht genug. Zurückgestellt."}, {"id": "L28", "act": "V", "start": 217.893, "end": 226.057, "en": "The third improves, measured by an evaluator it cannot touch. Accepted. Versioned. Reversible.", "de": "Die dritte verbessert sich – gemessen von einem Evaluator, den sie nicht berühren kann. Angenommen. Versioniert. Umkehrbar."}, {"id": "L29", "act": "V", "start": 227.857, "end": 234.643, "en": "Self-improvement is not accepting every change. It is learning from success, and from error.", "de": "Selbstverbesserung heißt nicht, jede Veränderung anzunehmen. Sie heißt, aus Erfolg und aus Irrtum zu lernen."}, {"id": "L30", "act": "V", "start": 236.043, "end": 242.78, "en": "New knowledge becomes meaningful when it changes how intelligence understands and improves itself.", "de": "Neues Wissen wird bedeutsam, wenn es verändert, wie Intelligenz sich selbst versteht und verbessert."}, {"id": "L31", "act": "VI", "start": 247.78, "end": 252.582, "en": "The mirror, again. The same self, and not the same.", "de": "Wieder der Spiegel. Dasselbe Selbst – und nicht dasselbe."}, {"id": "L32", "act": "VI", "start": 254.182, "end": 259.773, "en": "Behind her: every relation, every correction, every failed attempt she chose to keep.", "de": "Hinter ihr: jede Beziehung, jede Korrektur, jeder gescheiterte Versuch, den sie bewahren wollte."}, {"id": "L33", "act": "VI", "start": 261.973, "end": 265.639, "en": "The goal is not an intelligence that has finished learning.", "de": "Das Ziel ist keine Intelligenz, die fertig gelernt hat."}, {"id": "L34", "act": "VI", "start": 266.839, "end": 270.286, "en": "The goal is an intelligence that learns how to become.", "de": "Das Ziel ist eine Intelligenz, die lernt, wie man wird."}], "end_card": {"title": "NYXA", "tagline": "One Self. Many Minds. Multiple Learning Timescales. Governed Evolution.", "series": "Digitalleria · The Architecture of Becoming · Episode 01"}, "title": "NYXA – The Architecture of Becoming", "subtitles": {"en": [{"start": 4.0, "end": 7.228, "text": "An intelligence can know\nmillions of things about the world."}, {"start": 7.878, "end": 10.745, "text": "But what does it know about itself?"}, {"start": 13.095, "end": 19.355, "text": "This is Sophia. She is not the\nwhole of NYXA. She is one of its faces."}, {"start": 20.505, "end": 23.27, "text": "Behind the face, there is no single model."}, {"start": 23.31, "end": 27.566, "text": "There are many minds, and\none self that holds them together."}, {"start": 28.916, "end": 34.006, "text": "A self-model is not a claim to\nconsciousness. It is an architecture:"}, {"start": 34.046, "end": 39.362, "text": "a way for a system to represent\nits history, its abilities, its limits,"}, {"start": 39.402, "end": 40.784, "text": "and its change."}, {"start": 45.534, "end": 48.658, "text": "A self is not merely what exists now."}, {"start": 49.208, "end": 53.173, "text": "It is also what has been\nexperienced, what has been learned,"}, {"start": 53.213, "end": 55.399, "text": "and what may become possible."}, {"start": 56.949, "end": 60.03, "text": "Every experience enters with\nits origin attached:"}, {"start": 60.07, "end": 63.695, "text": "who observed it, when, and how\ncertain anyone can be."}, {"start": 64.645, "end": 69.188, "text": "A fact. A claim. An\ninterpretation. A hypothesis."}, {"start": 69.228, "end": 73.781, "text": "They are not allowed to blur into one another."}, {"start": 75.331, "end": 80.824, "text": "Meaning does not live in a single memory. It\nlives in the relations between them."}, {"start": 81.974, "end": 84.084, "text": "And a relation can be wrong."}, {"start": 84.124, "end": 90.286, "text": "So it can be examined, weakened,\ncorrected, without erasing what came before."}, {"start": 94.536, "end": 100.915, "text": "Intelligence does not evolve in isolation.\nIt evolves through relationships."}, {"start": 102.465, "end": 107.895, "text": "Two perspectives on the same horizon.\nNeither becomes a copy of the other."}, {"start": 109.245, "end": 114.899, "text": "What Sophia may remember is not\nhers to decide alone. Consent comes first."}, {"start": 116.249, "end": 120.398, "text": "A shared experience changes both\nof them, but differently."}, {"start": 120.438, "end": 123.072, "text": "That difference is worth keeping."}, {"start": 128.022, "end": 132.196, "text": "When no one is speaking, the architecture\nis designed to keep thinking."}, {"start": 132.946, "end": 139.359, "text": "Perceive. Process. Plan. Reflect. Consolidate."}, {"start": 140.109, "end": 143.646, "text": "Up to a third of this rhythm is\nreserved for reflection."}, {"start": 145.396, "end": 152.218, "text": "What did I understand? What did I\nmisunderstand? What should I learn from this?"}, {"start": 153.768, "end": 158.128, "text": "In consolidation, experiences\nare replayed, compared,"}, {"start": 158.168, "end": 162.402, "text": "and compressed into\ncandidates. Not into truths."}, {"start": 163.552, "end": 169.864, "text": "A machine does not dream as we do.\nBut it can return to its day, and look again."}, {"start": 171.014, "end": 175.629, "text": "Nothing it concludes here becomes\npart of the self until it has been checked,"}, {"start": 175.669, "end": 177.309, "text": "and a human has agreed."}, {"start": 182.259, "end": 188.074, "text": "Outside, science keeps moving.\nEvery week, new light."}, {"start": 189.024, "end": 191.115, "text": "Research agents read, compare,"}, {"start": 191.155, "end": 196.094, "text": "and relate each finding to the\narchitecture as it actually exists."}, {"start": 197.444, "end": 204.253, "text": "A weakness is found. Three alternatives are\nproposed, and tested in isolation."}, {"start": 205.803, "end": 211.314, "text": "The first looks brilliant, until\nit learns to please its own judge. Rejected."}, {"start": 212.464, "end": 216.743, "text": "The second is honest, but not enough. Held."}, {"start": 217.893, "end": 225.051, "text": "The third improves, measured by an evaluator\nit cannot touch. Accepted. Versioned."}, {"start": 225.091, "end": 226.307, "text": "Reversible."}, {"start": 227.857, "end": 231.322, "text": "Self-improvement is\nnot accepting every change."}, {"start": 231.362, "end": 234.893, "text": "It is learning from success, and from error."}, {"start": 236.043, "end": 241.629, "text": "New knowledge becomes meaningful when\nit changes how intelligence understands and"}, {"start": 241.669, "end": 243.03, "text": "improves itself."}, {"start": 247.78, "end": 252.832, "text": "The mirror, again. The\nsame self, and not the same."}, {"start": 254.182, "end": 254.874, "text": "Behind her:"}, {"start": 254.914, "end": 260.023, "text": "every relation, every correction, every\nfailed attempt she chose to keep."}, {"start": 261.973, "end": 265.889, "text": "The goal is not an intelligence\nthat has finished learning."}, {"start": 266.839, "end": 270.536, "text": "The goal is an intelligence that\nlearns how to become."}], "de": [{"start": 4.0, "end": 7.228, "text": "Eine Intelligenz kann Millionen\nDinge über die Welt wissen."}, {"start": 7.878, "end": 10.745, "text": "Doch was weiß sie über sich selbst?"}, {"start": 13.095, "end": 19.355, "text": "Das ist Sophia. Sie ist nicht\nganz NYXA. Sie ist eines ihrer Gesichter."}, {"start": 20.505, "end": 23.485, "text": "Hinter dem Gesicht\nsteht kein einzelnes Modell."}, {"start": 23.525, "end": 27.566, "text": "Es sind viele Minds – und\nein Selbst, das sie zusammenhält."}, {"start": 28.916, "end": 33.475, "text": "Ein Selbstmodell ist kein Anspruch\nauf Bewusstsein. Es ist eine Architektur:"}, {"start": 33.515, "end": 37.468, "text": "eine Weise, in der ein System\nseine Geschichte, seine Fähigkeiten,"}, {"start": 37.508, "end": 40.784, "text": "seine Grenzen und seine\nVeränderung repräsentiert."}, {"start": 45.534, "end": 48.658, "text": "Ein Selbst ist nicht\nnur das, was jetzt existiert."}, {"start": 49.208, "end": 51.714, "text": "Es ist auch das, was erfahren wurde,"}, {"start": 51.754, "end": 55.399, "text": "was gelernt wurde –\nund was möglich werden kann."}, {"start": 56.949, "end": 59.507, "text": "Jede Erfahrung kommt mit ihrer Herkunft:"}, {"start": 59.547, "end": 63.695, "text": "wer sie beobachtet hat, wann – und\nwie sicher man sein kann."}, {"start": 64.645, "end": 69.988, "text": "Ein Fakt. Eine Behauptung.\nEine Interpretation. Eine Hypothese."}, {"start": 70.028, "end": 73.781, "text": "Sie dürfen nicht ineinander verschwimmen."}, {"start": 75.331, "end": 78.131, "text": "Bedeutung wohnt nicht\nin einer einzelnen Erinnerung."}, {"start": 78.171, "end": 80.824, "text": "Sie wohnt in den Beziehungen zwischen ihnen."}, {"start": 81.974, "end": 84.219, "text": "Und eine Beziehung kann falsch sein."}, {"start": 84.259, "end": 89.044, "text": "Also kann sie geprüft, abgeschwächt\nund korrigiert werden – ohne zu löschen,"}, {"start": 89.084, "end": 90.286, "text": "was vorher war."}, {"start": 94.536, "end": 100.915, "text": "Intelligenz entwickelt sich nicht isoliert.\nSie entwickelt sich durch Beziehungen."}, {"start": 102.465, "end": 107.895, "text": "Zwei Perspektiven auf denselben\nHorizont. Keine wird zur Kopie der anderen."}, {"start": 109.245, "end": 112.85, "text": "Was Sophia sich merken darf,\nentscheidet sie nicht allein."}, {"start": 112.89, "end": 114.899, "text": "Zuerst kommt die Zustimmung."}, {"start": 116.249, "end": 119.821, "text": "Eine gemeinsame Erfahrung verändert\nbeide – aber verschieden."}, {"start": 119.861, "end": 123.072, "text": "Dieser Unterschied ist\nes wert, bewahrt zu werden."}, {"start": 128.022, "end": 132.196, "text": "Wenn niemand spricht, ist die Architektur\ndarauf angelegt, weiterzudenken."}, {"start": 132.946, "end": 139.359, "text": "Wahrnehmen. Verarbeiten.\nPlanen. Reflektieren. Konsolidieren."}, {"start": 140.109, "end": 143.646, "text": "Bis zu einem Drittel dieses\nRhythmus ist der Reflexion vorbehalten."}, {"start": 145.396, "end": 152.218, "text": "Was habe ich verstanden? Was habe ich\nmissverstanden? Was sollte ich daraus lernen?"}, {"start": 153.768, "end": 157.703, "text": "In der Konsolidierung\nwerden Erfahrungen wiedergegeben,"}, {"start": 157.743, "end": 162.402, "text": "verglichen und zu Kandidaten\nverdichtet. Nicht zu Wahrheiten."}, {"start": 163.552, "end": 165.634, "text": "Eine Maschine träumt nicht wie wir."}, {"start": 165.674, "end": 169.864, "text": "Aber sie kann zu ihrem Tag\nzurückkehren und noch einmal hinsehen."}, {"start": 171.014, "end": 173.938, "text": "Nichts, was sie hier\nfolgert, wird Teil des Selbst,"}, {"start": 173.978, "end": 177.309, "text": "bevor es geprüft wurde und ein\nMensch zugestimmt hat."}, {"start": 182.259, "end": 188.074, "text": "Draußen bewegt sich die Wissenschaft\nweiter. Jede Woche neues Licht."}, {"start": 189.024, "end": 190.28, "text": "Research-Agenten lesen,"}, {"start": 190.32, "end": 194.113, "text": "vergleichen und setzen jede Erkenntnis\nin Beziehung zur Architektur,"}, {"start": 194.153, "end": 196.094, "text": "wie sie tatsächlich existiert."}, {"start": 197.444, "end": 199.422, "text": "Eine Schwäche wird gefunden."}, {"start": 199.462, "end": 204.253, "text": "Drei Alternativen werden\nvorgeschlagen – und isoliert getestet."}, {"start": 205.803, "end": 210.412, "text": "Die erste wirkt brillant – bis sie\nlernt, ihrem eigenen Richter zu gefallen."}, {"start": 210.452, "end": 211.314, "text": "Verworfen."}, {"start": 212.464, "end": 216.743, "text": "Die zweite ist ehrlich,\naber nicht genug. Zurückgestellt."}, {"start": 217.893, "end": 221.734, "text": "Die dritte verbessert sich\n– gemessen von einem Evaluator,"}, {"start": 221.774, "end": 226.307, "text": "den sie nicht berühren kann.\nAngenommen. Versioniert. Umkehrbar."}, {"start": 227.857, "end": 231.622, "text": "Selbstverbesserung heißt\nnicht, jede Veränderung anzunehmen."}, {"start": 231.662, "end": 234.893, "text": "Sie heißt, aus Erfolg und\naus Irrtum zu lernen."}, {"start": 236.043, "end": 239.201, "text": "Neues Wissen wird\nbedeutsam, wenn es verändert,"}, {"start": 239.241, "end": 243.03, "text": "wie Intelligenz sich\nselbst versteht und verbessert."}, {"start": 247.78, "end": 252.832, "text": "Wieder der Spiegel. Dasselbe\nSelbst – und nicht dasselbe."}, {"start": 254.182, "end": 254.789, "text": "Hinter ihr:"}, {"start": 254.829, "end": 260.023, "text": "jede Beziehung, jede Korrektur, jeder\ngescheiterte Versuch, den sie bewahren wollte."}, {"start": 261.973, "end": 265.889, "text": "Das Ziel ist keine Intelligenz,\ndie fertig gelernt hat."}, {"start": 266.839, "end": 270.536, "text": "Das Ziel ist eine Intelligenz,\ndie lernt, wie man wird."}]}};
